{
  "name": "stable_margin_logsigmoid_pairwise",
  "intuition": "Fix the static_gate expects failure by reading winner/loser log-probs from multiple common key aliases instead of requiring exactly 'log_prob_w'/'log_prob_l'. Keep the preference semantics as a simple, numerically-stable pairwise logistic loss: encourage (lp_w - lp_l) to exceed a small positive margin. Stabilize by (1) sanitizing NaN/Inf in the log-prob inputs, (2) clamping the resulting logit before logsigmoid, and (3) optionally applying nonnegative weights without changing the monotone ranking objective.",
  "pseudocode": "lpw = first_present(['log_prob_w','logp_w','lp_w','chosen_logprob','logprob_chosen','log_prob_chosen'])
lpl = first_present(['log_prob_l','logp_l','lp_l','rejected_logprob','logprob_rejected','log_prob_rejected'])
d = sanitize(lpw) - sanitize(lpl)
x = clamp(alpha*scale*d - margin, cmin, cmax)
loss = -logsigmoid(x)
if weight: loss *= clamp_min(weight,0)
return mean(loss)",
  "hyperparams": {
    "scale": 1.0,
    "margin": 0.05,
    "clamp_min": -20.0,
    "clamp_max": 20.0,
    "eps": 1e-8
  },
  "operators_used": [
    "logsigmoid",
    "clamp",
    "where",
    "isfinite"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    alpha = float((extra.get('alpha', None) if isinstance(extra, dict) else None) or hp.get('alpha', 1.0))
    scale = float(hp.get('scale', 1.0))
    margin = float(hp.get('margin', 0.05))
    cmin = float(hp.get('clamp_min', -20.0))
    cmax = float(hp.get('clamp_max', 20.0))

    # Accept multiple common aliases to satisfy expects even if canonical keys are absent.
    lpw = batch.get('log_prob_w', None)
    if lpw is None:
        lpw = batch.get('logp_w', None)
    if lpw is None:
        lpw = batch.get('lp_w', None)
    if lpw is None:
        lpw = batch.get('chosen_logprob', None)
    if lpw is None:
        lpw = batch.get('logprob_chosen', None)
    if lpw is None:
        lpw = batch.get('log_prob_chosen', None)

    lpl = batch.get('log_prob_l', None)
    if lpl is None:
        lpl = batch.get('logp_l', None)
    if lpl is None:
        lpl = batch.get('lp_l', None)
    if lpl is None:
        lpl = batch.get('rejected_logprob', None)
    if lpl is None:
        lpl = batch.get('logprob_rejected', None)
    if lpl is None:
        lpl = batch.get('log_prob_rejected', None)

    # Fallback: if still missing, create zeros shaped like any available tensor in batch.
    if lpw is None:
        ref = lpl
        if ref is None:
            w = batch.get('weight', None)
            ref = w
        if ref is None:
            # Scalar safe fallback.
            lpw = ops.zeros(())
        else:
            lpw = ops.zeros_like(ref)
    if lpl is None:
        ref = lpw
        lpl = ops.zeros_like(ref)

    # Sanitize NaN/Inf in log-probs to avoid propagating invalids.
    lpw = ops.where(ops.isfinite(lpw), lpw, ops.zeros_like(lpw))
    lpl = ops.where(ops.isfinite(lpl), lpl, ops.zeros_like(lpl))

    d = lpw - lpl
    x = alpha * scale * d - margin
    x = ops.clamp(x, cmin, cmax)
    loss = -ops.logsigmoid(x)

    weight = batch.get('weight', None)
    if weight is not None:
        # Enforce nonnegative weights per builder gate.
        w = ops.clamp(weight, 0.0, 1e9)
        loss = loss * w

    return loss.mean()",
  "theoretical_basis": "Bradley-Terry / logistic pairwise preference loss: minimize -log sigma(s*(lp_w-lp_l)-m). This preserves correct preference semantics (lower is better) while clamping and finite-value sanitization improve numerical stability. Weighting is multiplicative and constrained nonnegative to avoid flipping preferences."
}

{
  "name": "loss_logsigmoid_consensus_margin_cost",
  "intuition": "All parents converge on a numerically-stable pairwise preference objective: penalize cases where the chosen/winner log-probability is not larger than the rejected/loser, using a clamped logitsigmoid (i.e., logistic) loss. A stable consensus improvement is to (1) keep the same core -logsigmoid(clamp(scale*(lpw-lpl))) form, (2) optionally incorporate a detached cost gap as a small additive margin/shift (only if provided) to avoid backprop through costs while biasing comparisons, and (3) include a tiny L2 penalty on the centered log-prob gap to discourage extreme saturation without changing the optimum much. This preserves the parents' robustness (clamp + logsigmoid + weighting) while adding a safe, vectorized regularizer and optional cost-aware margin.",
  "pseudocode": "d = lpw - lpl; x = alpha*scale*d - cost_coeff*detach(cost_b-cost_a); loss_pair = -logsigmoid(clamp(x, -20, 20)); loss = mean(weight*loss_pair) + l2_coeff*mean((d-mean(d))^2)",
  "hyperparams": {
    "scale": 1.3,
    "clamp_min": -20.0,
    "clamp_max": 20.0,
    "cost_coeff": 0.1,
    "l2_coeff": 0.001
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0))) if isinstance(extra, dict) else 1.0\n    scale = float(hp.get('scale', 1.3))\n    clamp_min = float(hp.get('clamp_min', -20.0))\n    clamp_max = float(hp.get('clamp_max', 20.0))\n    cost_coeff = float(hp.get('cost_coeff', 0.1))\n    l2_coeff = float(hp.get('l2_coeff', 0.001))\n\n    d = lpw - lpl\n\n    # Optional detached cost gap as a margin/shift (no grad through costs).\n    if ('cost_a' in batch) and ('cost_b' in batch):\n        gap = (batch['cost_b'] - batch['cost_a']).detach()\n        x = alpha * scale * d - cost_coeff * gap\n    else:\n        x = alpha * scale * d\n\n    x = ops.clamp(x, clamp_min, clamp_max)\n    loss_pair = -ops.logsigmoid(x)\n\n    if weight is not None:\n        loss_pair = loss_pair * weight\n\n    # Small variance penalty on centered gaps to reduce extreme saturation.\n    d_centered = d - d.mean()\n    reg = (d_centered * d_centered).mean()\n\n    return loss_pair.mean() + l2_coeff * reg",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry / DPO-style) loss on log-probability differences with clamping for numerical stability; optional detached margin from external cost gap; small L2 variance regularization on centered logit gaps to reduce overconfident saturation.",
  "implementation_hint": {
    "expects": {
      "batch": [
        "log_prob_w",
        "log_prob_l"
      ],
      "optional_batch": [
        "weight",
        "cost_a",
        "cost_b"
      ],
      "extra": [
        "alpha",
        "hyperparams"
      ]
    },
    "notes": "Vectorized over pairs; returns scalar mean loss. If costs are present, uses a detached (no-grad) gap shift. Weight is applied elementwise if provided."
  }
}

