{
  "name": "loss_logsigmoid_crossover_costmargin_001",
  "intuition": "Remove unsupported `expects`/config plumbing (no `alpha` or nested `hyperparams` access) and make the loss fully self-contained and stable. Keep the core pairwise -logsigmoid objective, optionally apply a detached cost-gap margin, clamp logits to prevent overflow, and normalize weights defensively (clamp nonnegative and divide by sum) to avoid scale/NaN issues when weights are present.",
  "pseudocode": "x = clamp(scale*(lpw-lpl) - cost_coef*detach(cost_b-cost_a), -20, 20); loss = -logsigmoid(x); if weight: w=clamp(weight,0,inf); return sum(w*loss)/max(sum(w),eps) else mean(loss)",
  "hyperparams": {
    "scale": 1.1,
    "cost_coef": 0.1,
    "eps": 1e-08
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)

    scale = 1.1
    cost_coef = 0.1
    eps = 1e-8
    if isinstance(extra, dict):
        # Only accept flat numeric overrides (avoid unsupported expects keys like 'alpha'/'hyperparams')
        if 'scale' in extra:
            scale = float(extra['scale'])
        if 'cost_coef' in extra:
            cost_coef = float(extra['cost_coef'])
        if 'eps' in extra:
            eps = float(extra['eps'])

    x = scale * (lpw - lpl)

    if ('cost_a' in batch) and ('cost_b' in batch):
        gap = (batch['cost_b'] - batch['cost_a']).detach()
        x = x - cost_coef * gap

    x = ops.clamp(x, -20.0, 20.0)
    per_pair = -ops.logsigmoid(x)

    if weight is None:
        return per_pair.mean()

    w = ops.clamp(weight, 0.0, 1e9)
    denom = ops.clamp(w.sum(), eps, 1e30)
    return (per_pair * w).sum() / denom",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry / DPO-style) ranking loss with an additive detached cost-based margin; clamping improves numerical stability; weight normalization prevents loss-scale explosions and avoids NaNs when weights sum to ~0."
}

{
  "name": "loss_logsigmoid_004_label_smooth",
  "intuition": "Adds a small label-smoothing mix between the standard pairwise -logsigmoid margin loss and its symmetric counterpart to reduce overconfidence on noisy/ambiguous preference pairs. This keeps the same stable margin structure (clamped) while improving generalization by preventing extremely confident updates when lpw-lpl is large.",
  "pseudocode": "x = clamp(alpha*scale*(lpw-lpl), -20, 20); loss_pos = -logsigmoid(x); loss_neg = -logsigmoid(-x); loss = (1-eps)*loss_pos + eps*loss_neg",
