{
  "name": "loss_logsigmoid_004_label_smooth_stable_expects",
  "intuition": "Fixes the static gate by explicitly declaring required batch keys in expects while keeping the original numerically-stable pairwise logistic margin loss. Stabilization is preserved via margin clamping, and label smoothing stays bounded by clamping eps into [0, 0.5] to avoid preference-semantics inversion or negative mixing weights. Also clamps optional weights to be non-negative to match builder constraints and prevent sign-flipped gradients.",
  "pseudocode": "require log_prob_w, log_prob_l; x = clamp(alpha*scale*(lpw-lpl), -20, 20); eps = clamp(eps, 0, 0.5); loss = (1-eps)*(-logsigmoid(x)) + eps*(-logsigmoid(-x)); if weight: loss *= clamp(weight, 0, inf); return mean(loss)",
  "hyperparams": {
    "scale": 1.5073452222319776,
    "label_smoothing": 0.05
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "expects": {
    "batch": [
      "log_prob_w",
      "log_prob_l"
    ],
    "optional_batch": [
      "weight"
    ],
    "model_output": [],
    "extra": [
      "alpha",
      "hyperparams"
    ]
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch[\"log_prob_w\"]\n    lpl = batch[\"log_prob_l\"]\n    weight = batch.get(\"weight\", None)\n\n    hp = extra.get(\"hyperparams\", {})\n    alpha = float(extra.get(\"alpha\", hp.get(\"alpha\", 1.0)))\n    scale = float(hp.get(\"scale\", 1.5073452222319776))\n    eps = float(hp.get(\"label_smoothing\", 0.05))\n\n    # Keep label smoothing in a safe range so mixing weights remain valid.\n    eps_t = ops.clamp(lpw * 0.0 + eps, 0.0, 0.5)\n\n    x = alpha * scale * (lpw - lpl)\n    x = ops.clamp(x, -20.0, 20.0)\n\n    loss_pos = -ops.logsigmoid(x)\n    loss_neg = -ops.logsigmoid(-x)\n    loss = (1.0 - eps_t) * loss_pos + eps_t * loss_neg\n\n    if weight is not None:\n        loss = loss * ops.clamp(weight, 0.0, 1.0e9)\n\n    return loss.mean()",
  "theoretical_basis": "Pairwise Bradley-Terry logistic preference loss on the log-probability margin with bounded label smoothing (a convex mixture of positive/negative logistic losses) and margin clamping for numerical stability; optional non-negative instance weighting preserves preference direction."
}

{
  "name": "loss_logsigmoid_004_label_smooth_fix_expects",
  "intuition": "Stabilize and simplify the pairwise logistic preference loss while matching the required expects schema: use the standard margin (log_prob_w - log_prob_l), clamp it to avoid extreme values, and apply light label-smoothing by mixing -logsigmoid(m) with -logsigmoid(-m). This preserves preference semantics (winner should have higher log-prob) and prevents numerical/gradient spikes; also handles optional nonnegative weights safely.",
  "pseudocode": "m = clamp(alpha*scale*(log_prob_w-log_prob_l), -20, 20); loss = (1-eps)*(-logsigmoid(m)) + eps*(-logsigmoid(-m)); return mean(loss*weight_if_present)",
