  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    scale = float(hp.get('scale', 1.5073452222319776))\n    eps = float(hp.get('label_smoothing', 0.05))\n    cmin = float(hp.get('clamp_min', -20.0))\n    cmax = float(hp.get('clamp_max', 20.0))\n\n    # Pairwise margin: positive when winner is higher probability.\n    m = alpha * scale * (log_prob_w - log_prob_l)\n    m = ops.clamp(m, cmin, cmax)\n\n    loss_pos = -ops.logsigmoid(m)\n    loss_neg = -ops.logsigmoid(-m)\n    loss = (1.0 - eps) * loss_pos + eps * loss_neg\n\n    if weight is not None:\n        # Builder gate expects nonnegative weights; clamp for safety.\n        loss = loss * ops.clamp(weight, 0.0, 1e9)\n\n    return loss.mean()",
  "theoretical_basis": "Bradley-Terry / logistic pairwise preference loss on log-prob margins; label smoothing corresponds to mixing the target away from a hard preference toward uncertainty (0.5), improving robustness under noisy comparisons while keeping the same stable convex-in-margin form."
}
